def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the solid separator.
    sep = next(r for r, row in enumerate(grid)
               if len(set(row)) == 1 and 0 < r < h - 1)
    top, bottom = grid[:sep], grid[sep + 1:]
    n = min(len(top), len(bottom))

    # The two panels encode sparse marks against their dominant colors;
    # combine the marks in aligned positions.
    def background(panel):
        vals = [x for row in panel for x in row]
        return max(set(vals), key=vals.count)

    bg1, bg2 = background(top), background(bottom)
    return [
        [3 if top[r][c] != bg1 or bottom[r][c] != bg2 else 1
         for c in range(w)]
        for r in range(n)
    ]
