def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid divider and take the panel before it (or to its left).
    divider_row = next((r for r, row in enumerate(grid)
                        if len(set(row)) == 1 and 0 < r < h - 1), None)
    divider_col = next((c for c in range(w)
                        if all(row[c] == grid[0][c] for row in grid)
                        and 0 < c < w - 1), None)

    if divider_row is not None:
        panel = grid[:divider_row]
    elif divider_col is not None:
        panel = [row[:divider_col] for row in grid]
    else:
        panel = grid

    from collections import Counter
    counts = Counter(x for row in panel for x in row)
    background = counts.most_common(1)[0][0]
    return [[1 if x == background else 3 for x in row] for row in panel]
